import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';
import { color, uv, mix, step } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  const toDispose = [];

  // Backdrop gradient material using TSL
  const createBackdropMaterial = () => {
    const vUv = uv();
    const y = vUv.y;

    const c0 = color(0x0b0b10);
    const c1 = color(0x101017);
    const c2 = color(0x16161d);

    const t1 = y.div(0.55).clamp(0, 1);
    const t2 = y.sub(0.55).div(0.45).clamp(0, 1);

    const blend1 = mix(c0, c1, t1);
    const blend2 = mix(c1, c2, t2);
    const finalColor = mix(blend1, blend2, step(0.55, y));

    const material = new THREE.MeshBasicNodeMaterial();
    material.colorNode = finalColor;
    return material;
  };

  const backdropMaterial = createBackdropMaterial();
  const backdropGeometry = new THREE.PlaneGeometry(7, 6);
  const backdrop = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  backdrop.renderOrder = 0;
  group.add(backdrop);
  toDispose.push(backdropGeometry, backdropMaterial);

  // Plinth cylinder
  const plinthGeometry = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 32);
  const plinthMaterial = new THREE.MeshStandardMaterial({
    color: 0x14141a,
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeometry, plinthMaterial);
  plinth.position.y = -1.1;
  group.add(plinth);
  toDispose.push(plinthGeometry, plinthMaterial);

  // Contact shadow with radial gradient using TSL
  const createShadowMaterial = () => {
    const vUv = uv();
    const dist = vUv.sub(0.5).length().mul(2);
    const alpha = mix(0.55, 0, dist.clamp(0, 1));

    const material = new THREE.MeshBasicNodeMaterial({ transparent: true });
    material.colorNode = color(0x000000);
    material.opacityNode = alpha;
    return material;
  };

  const shadowMaterial = createShadowMaterial();
  const shadowGeometry = new THREE.PlaneGeometry(3.2, 3.2);
  const shadow = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadow.position.set(0, -1.101, 0.001);
  shadow.renderOrder = 1;
  group.add(shadow);
  toDispose.push(shadowGeometry, shadowMaterial);

  // Load and process watch mesh
  const gltf = ctx.glbLoader.load(config.meshUrl);
  const watch = gltf.scene.clone();

  const box = new THREE.Box3().setFromObject(watch);
  const modelHeight = box.max.y - box.min.y;
  const scale = 2.2 / modelHeight;
  watch.scale.multiplyScalar(scale);

  const modelCenter = box.getCenter(new THREE.Vector3());
  watch.position.y = -modelCenter.y * scale;
  watch.position.x = -modelCenter.x * scale;
  watch.position.z = -modelCenter.z * scale;

  const watchGroup = new THREE.Group();
  watchGroup.add(watch);
  group.add(watchGroup);

  // Accent rim light: red highlight on left case flank
  const rimLight = new THREE.PointLight(0xff2a38, 1.6, 10);
  rimLight.position.set(-1.2, 0.5, 0.8);
  watchGroup.add(rimLight);

  // Text labels
  const textGroup = new THREE.Group();

  const textContent = config.textContent || {
    headline: 'Calibre NA-01',
    body: 'Machined in-house. 41 mm. Grade 5 titanium.',
    caption: 'FROM 4200 USD / SHIPS IN 21 DAYS',
  };

  const createTextMesh = (text, fontSize, color) => {
    const mesh = ctx.fontAtlas.createTextMesh(text, {
      fontSize,
      color,
      fontWeight: fontSize === 0.34 ? 600 : 400,
    });
    const tBox = new THREE.Box3().setFromObject(mesh);
    const width = tBox.max.x - tBox.min.x;
    mesh.position.x = -width / 2;
    return mesh;
  };

  const headline = createTextMesh(textContent.headline, 0.34, 0xe8ecf2);
  headline.position.y = -1.5;
  headline.position.z = 0.1;
  textGroup.add(headline);

  const body = createTextMesh(textContent.body, 0.13, 0xe8ecf2);
  body.position.y = -1.75;
  body.position.z = 0.1;
  textGroup.add(body);

  const caption = createTextMesh(textContent.caption, 0.09, 0xff2a38);
  caption.position.y = -2.0;
  caption.position.z = 0.1;
  textGroup.add(caption);

  group.add(textGroup);

  // Apply cinematic primitives
  ctx.primitives['orbit'](watchGroup, { speed: 0.15, radius: 0.6 });
  ctx.primitives['depth-rotate'](watchGroup, { maxDeg: 6 });

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    toDispose.forEach((obj) => {
      if (obj.dispose) obj.dispose();
    });

    watch.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });

    textGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) child.material.dispose();
    });
  };

  return group;
}
